  const CILS = [B('dret', 'cyl', [14, 14, 36], -30, 0, 0, '#3D7BF4'), B('x90', 'cyl', [14, 14, 36], 0, 0, 0, '#2FB36D', { r: [90, 0, 0], h: 14 }), B('y90', 'cyl', [14, 14, 36], 32, 0, 0, '#FF8A3D', { r: [0, 90, 0], h: 14 })];
