  const PORTA0 = [CASA, TEU, B('porta', 'box', [24, 2, 30], 0, -15.5, 0, '#A0683A')], PORTA1 = [CASA, TEU, B('porta', 'box', [12, 2, 15], 0, -15.5, 0, '#A0683A')];
  // ---- m3-4 · el robot de peces (la fitxa tècnica) ----
